#!/usr/bin/env python3
"""Generate rtl/qsag_p2_rc.sv: the 118 Poseidon2 width-12 round constants and the 24 Keccak iota
constants, from the reference model (model/qsag_prims.py)."""
import os
import sys

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "model"))
import qsag_prims as q  # noqa: E402

out = [
    "// GENERATED by scripts/gen_p2_rc.py from model/qsag_prims.py. Do not edit.",
    "// idx 0..47: first full rounds (round*12 + lane), 48..95: last full rounds, 96..117: partial rounds.",
    "`default_nettype none",
    "module qsag_p2_rc (",
    "    input  wire  [6:0]  idx,",
    "    output logic [63:0] rc",
    ");",
    "    always_comb begin",
    "        unique case (idx)",
]
for i, c in enumerate(q.p2_rc_table()):
    out.append(f"            7'd{i}: rc = 64'h{c:016x};")
out += [
    "            default: rc = 64'h0;",
    "        endcase",
    "    end",
    "endmodule",
    "",
    "module qsag_keccak_rc (",
    "    input  wire  [4:0]  idx,",
    "    output logic [63:0] rc",
    ");",
    "    always_comb begin",
    "        unique case (idx)",
]
for i, c in enumerate(q.KECCAK_RC):
    out.append(f"            5'd{i}: rc = 64'h{c:016x};")
out += ["            default: rc = 64'h0;", "        endcase", "    end", "endmodule", "`default_nettype wire", ""]
open(sys.argv[1], "w").write("\n".join(out))
print("wrote", sys.argv[1])
